function validate([points, angle, location]) {
  const coord = v => Number.isInteger(v) && v >= 0 && v <= 100;
  if (!Array.isArray(points) || points.length < 1 || points.length > 100000) return 'points needs 1 to 10^5 entries.';
  if (points.some(p => !Array.isArray(p) || p.length !== 2 || !coord(p[0]) || !coord(p[1]))) return 'Each point is [x, y] with whole numbers from 0 to 100.';
  if (!Number.isInteger(angle) || angle < 0 || angle >= 360) return 'angle is a whole number from 0 to 359.';
  if (!Array.isArray(location) || location.length !== 2 || !coord(location[0]) || !coord(location[1])) return 'location is [x, y] with whole numbers from 0 to 100.';
  return null;
}

