function visiblePoints(points, angle, location) {
  const [px, py] = location;
  const angles = [];
  let same = 0;
  for (const [x, y] of points) {
    if (x === px && y === py) {
      same++;
    } else {
      angles.push(Math.atan2(y - py, x - px) * 180 / Math.PI);
    }
  }
  angles.sort((a, b) => a - b);
  const count = angles.length;
  for (let i = 0; i < count; i++) {
    angles.push(angles[i] + 360);
  }

  let best = 0;
  let left = 0;
  for (let right = 0; right < angles.length; right++) {
    while (angles[right] - angles[left] > angle + 1e-9) {
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best + same;
}

