function visiblePoints(points, angle, location) {
  // Put the clockwise edge of the view on each point in turn and count the points
  // whose counterclockwise turn from it is at most angle.
  const [px, py] = location;
  const vectors = points.map(([x, y]) => [x - px, y - py]);
  const here = vectors.filter(([dx, dy]) => dx === 0 && dy === 0).length;
  const others = vectors.filter(([dx, dy]) => dx !== 0 || dy !== 0);
  let best = 0;
  for (const [ax, ay] of others) {
    let seen = 0;
    for (const [bx, by] of others) {
      let turn = Math.atan2(ax * by - ay * bx, ax * bx + ay * by) * 180 / Math.PI;
      if (turn < 0) turn += 360;
      if (turn <= angle + 1e-9) seen++;
    }
    best = Math.max(best, seen);
  }
  return best + here;
}

