function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const angles = [0, 45, 90, 135, 180, 270, 359];
  const angle = rand() < 0.5 ? angles[int(0, angles.length - 1)] : int(0, 359);
  if (size === 'large') {
    const location = [int(0, 100), int(0, 100)];
    const n = 2000;
    const points = Array.from({ length: n }, () => rand() < 0.02 ? [...location] : [int(0, 100), int(0, 100)]);
    return [points, angle, location];
  }
  // Small: a tight box around the location gives many shared directions and exact boundary angles.
  const location = [int(0, 100), int(0, 100)];
  const reach = int(1, 3);
  const clamp = v => Math.max(0, Math.min(100, v));
  const n = int(1, 8);
  const points = Array.from({ length: n }, () => [clamp(location[0] + int(-reach, reach)), clamp(location[1] + int(-reach, reach))]);
  return [points, angle, location];
}
